#!/bin/bash
# RTL pilot of one converted STR2RTS application: UCX-OS application generated by rttools.ucxgen
# from its CSV and .map, injection table at the clock of the flow, Questa simulation with
# experiments/exp23/simulate.sh, analysis of the log against the phase model (rttools.paper.rtlapp,
# rttools.paper.phasecheck), as experiments/car-v-rtl does for CAR-V.
#
#   pilot.sh <APP> <work dir> [<iterations>]
#
# <APP>:        paper name of an application of ../config.json (APP-CFIR, ...)
# <work dir>:   directory outside /home for the copy of the repository, the build and the simulation
#               (hundreds of MB); <work dir>/<name>/{repo,sim,results}
# <iterations>: complete iterations after the warm-up that the simulated time covers (default 10):
#               SIM_NS = warm-up 3 ms + (n(v_last) + iterations - 1) T + R_bound + T, rounded up to 0.5 ms
#               (the rule of experiments/car-v-rtl)
#
# The script changes no file of the repository tree it runs from, except its own outputs under
# rtl/<app dir>/ (generated <name>.{c,json,sim}, <name>_tt.h, events.txt, RUN_INFO, time.log,
# metrics.json and the CSV files of the analysis). It works on a copy of the repository in the work
# directory: the generated application goes to pkt-sim/software/ucx-os/app of the copy, and the
# UCX-OS Makefile builds it through GEN_APPS=<name> in MAKEFLAGS (the rule of the generated
# applications; the Makefile of the repository lists car_v, wcet_e, carv_e and e_ucx).
#
# Clock: the first F_CLK at or above f_search of the flow (../build/apps/<app>.json or
# ../reference.json) whose release period is a whole number of 16-cycle steps of TIMER1
# (F_CLK multiple of 16 / T Hz). The injection table takes the costs of the CSV (RUN_INFO costs=csv).
#
# Environment: ENV_SETUP (as simulate.sh, e.g. "source /usr/share/Modules/init/bash; module load
# riscv64-elf/12.2.0 questa/2025.3"), PYTHON (default python3), IMAGE_FLOW=1 (second run, after
# static_costs.py on the image of the first: the clock of the flow with t(v) = max(CSV, static) and the
# handler terms of that image, rtl/<app dir>/static.json, and the injection table with those costs, the
# procedure of the runs of experiments/tt; work in <work dir>/<name>_image, results in
# rtl/<app dir>/image-flow/), RAM_BYTES (optional, power of two:
# RAM of each PE in the simulation, default 65536; passes -gRAM_MSIZE to vsim and a copy of the
# linker script with that LENGTH to the build through LDSCRIPT in MAKEFLAGS), STEP=prepare stops
# after the generation and the heap check (no build, no simulation).
set -euo pipefail

APP=${1:?usage: pilot.sh <APP> <work dir> [<iterations>]}
WORK=${2:?usage: pilot.sh <APP> <work dir> [<iterations>]}
ITER=${3:-10}
PYTHON=${PYTHON:-python3}
HERE=$(cd "$(dirname "$0")" && pwd)
REPO=$(cd "$HERE/../../.." && pwd)
mkdir -p "$WORK"
WORK=$(cd "$WORK" && pwd)
case $WORK in /home/*) echo "work dir must be outside /home: $WORK" >&2; exit 2 ;; esac

# parameters of the run from the conversion and the analysis of the application
eval "$(PYTHONPATH= "$PYTHON" - "$APP" "$ITER" "$REPO" "${IMAGE_FLOW:-0}" "$HERE" <<'EOF'
import json, math, os, sys
from fractions import Fraction
app, iterations, repo = sys.argv[1], int(sys.argv[2]), sys.argv[3]
d = app.lower()
base = os.path.join(repo, "apps", "str2rts", d)
conv = json.load(open(os.path.join(base, "conversion.json")))
row = None
for path, pick in ((os.path.join(repo, "experiments", "str2rts", "build", "apps", d + ".json"), lambda m: m),
                   (os.path.join(repo, "experiments", "str2rts", "reference.json"), lambda m: m["apps"][app])):
    if os.path.exists(path):
        r = pick(json.load(open(path)))["row"]
        if r.get("f_search_hz") and r.get("r_bound_ms"):
            row = r
            break
if sys.argv[4] == "1":
    st = json.load(open(os.path.join(sys.argv[5], d, "static.json")))["flow_image"]
    row = dict(row or {}, f_search_hz=st["f_search_hz"], r_bound_ms=st["r_bound_ms"], phase_last=conv["phase_last"])
if row is None:
    sys.exit("no analysis result of " + app + " (make run)")
T = Fraction(str(conv["period_s"]))
grid = Fraction(16) / T
if grid.denominator != 1 or (Fraction(10 ** 9) / (T * 10 ** 9)).denominator != 1:
    sys.exit(f"T = {float(T)} s: 16 / T and 1 / T must be whole numbers of Hz (simulate.sh)")
f_clk = int(math.ceil(row["f_search_hz"] / grid - 1e-9) * grid)
need = Fraction(3, 1000) + (row["phase_last"] + iterations - 1) * T + Fraction(row["r_bound_ms"]) / 1000 + T
sim_ns = int(math.ceil(need * 2000)) * 500000
name = "str2rts_" + "".join(c for c in d.split("-", 1)[1] if c.isalnum())
print(f"DIR={d}; NAME={name}; CSV={conv['files']['csv']}; MAP={conv['files']['map']}; MESH={conv['mesh']}; "
      f"ARCH={conv['arch']}; F_CLK={f_clk}; RELEASE_NS={int(T * 10 ** 9)}; SIM_NS={sim_ns}; "
      f"F_SEARCH={row['f_search_hz']}")
EOF
)"
echo "$APP: $NAME, mesh $MESH, F_CLK $F_CLK Hz (f_search $F_SEARCH Hz), T $RELEASE_NS ns, $SIM_NS ns for $ITER iterations"

RUN=$WORK/$NAME
OUT=$HERE/$DIR
COSTS=
if [ "${IMAGE_FLOW:-0}" = 1 ]; then RUN=$WORK/${NAME}_image; COSTS=$OUT/costs_file.json; OUT=$OUT/image-flow; fi
COPY=$RUN/repo
mkdir -p "$RUN"
rsync -a --delete --exclude .git --exclude '/experiments/*/build/' --exclude __pycache__ --exclude '/experiments/str2rts/rtl/app-*/' \
	"$REPO/" "$COPY/"
APPDIR=$COPY/pkt-sim/software/ucx-os/app
SRC=$COPY/apps/str2rts/$DIR
GEN="env PYTHONPATH=$COPY/orca-rt-tools $PYTHON -W ignore -m rttools.ucxgen"
$GEN generate "$SRC/$CSV" "$SRC/$MAP" --name "$NAME" --mesh "$MESH" --out "$APPDIR"
TTCOSTS=
if [ -n "$COSTS" ]; then
	# the analysis of the run looks for the costs file of the table in experiments/wcet/costs/tt of its tree
	cp "$COSTS" "$COPY/experiments/wcet/costs/tt/$NAME.json"
	cp "${COSTS%.json}.handlers.json" "$COPY/experiments/wcet/costs/tt/$NAME.handlers.json"
	TTCOSTS="--costs $COPY/experiments/wcet/costs/tt/$NAME.json"
fi
$GEN tt "$SRC/$CSV" "$SRC/$MAP" --arch "$COPY/arch/$ARCH" --name "$NAME" --clock "$F_CLK" $TTCOSTS --out "$APPDIR"
mkdir -p "$OUT"
cp "$APPDIR/$NAME.c" "$APPDIR/$NAME.json" "$APPDIR/$NAME.sim" "$APPDIR/${NAME}_tt.h" "$OUT/"
# heap of the image of car_v built with riscv64-elf-gcc 12.2.0 (experiments/car-v-rtl/Makefile); the check
# after the build takes _heap_size of the image
HEAP=48176
RAM=${RAM_BYTES:-65536}
if [ "$RAM" != 65536 ]; then HEAP=$(( HEAP + RAM - 65536 )); fi
$GEN memory "$APPDIR/$NAME.json" --heap "$HEAP" --in-flight 2 --json "$RUN/memory_before_build.json" \
	|| { echo "$APP: the heap of a PE does not fit in $RAM bytes of RAM (RAM_BYTES)" >&2; exit 3; }
[ "${STEP:-}" = prepare ] && exit 0

FLAGS="GEN_APPS=$NAME"
VOPTS=${VSIM_OPTS:-}
if [ "$RAM" != 65536 ]; then
	(( RAM > 0 && (RAM & (RAM - 1)) == 0 )) || { echo "RAM_BYTES must be a power of two: $RAM" >&2; exit 2; }
	LD=$RUN/hf-risc-$RAM.ld
	sed "s/LENGTH = 64K/LENGTH = $RAM/" "$COPY/pkt-sim/software/ucx-os/arch/riscv/hf-riscv-e/hf-risc.ld" > "$LD"
	grep -q "LENGTH = $RAM" "$LD" || { echo "linker script: no LENGTH = 64K line" >&2; exit 2; }
	FLAGS="$FLAGS LDSCRIPT=$LD"
	VOPTS="$VOPTS -gRAM_MSIZE=$RAM"
fi
SECONDS=0
MAKEFLAGS="$FLAGS" VSIM_OPTS="$VOPTS" F_CLK=$F_CLK RELEASE_NS=$RELEASE_NS \
	"$COPY/experiments/exp23/simulate.sh" "$RUN/sim" "$SIM_NS" "$NAME" "$MESH"
echo "wall_s=$SECONDS" > "$RUN/wall.txt"
$GEN memory "$APPDIR/$NAME.json" --image-map "$RUN/sim/pkt-sim/software/ucx-os/build/target/image.map" \
	--in-flight 2 --json "$RUN/memory.json" || echo "$APP: heap check of the image failed" >&2

ANALYZE="env PYTHONPATH=$COPY/orca-rt-tools $PYTHON -W ignore -m"
$ANALYZE rttools.paper.rtlapp analyze "$RUN/sim/events.txt" --manifest "$APPDIR/$NAME.json" --csv "$SRC/$CSV" \
	--map "$SRC/$MAP" --arch "$COPY/arch/$ARCH" --out "$RUN/results"
$ANALYZE rttools.paper.phasecheck "$RUN/results/metrics.json" --rows 5 > "$RUN/results/phasecheck.txt" 2>&1 \
	|| echo "$APP: phasecheck reports phases that do not conform (results/phasecheck.txt)" >&2
cp "$RUN/sim/events.txt" "$RUN/sim/RUN_INFO" "$RUN/sim/time.log" "$RUN/wall.txt" "$RUN/memory.json" "$OUT/" 2>/dev/null || true
cp "$RUN/results/"*.json "$RUN/results/"*.csv "$RUN/results/phasecheck.txt" "$OUT/" 2>/dev/null || true
echo "$APP: results in $OUT (simulation in $RUN/sim, $SECONDS s)"
